const steps = [
  { step: 'Extract invoice number from PDF', mode: 'agentic', needs_judgement: false, output_shape: 'fixed', reversible: true, runs_per_day: 4000, cent_cost: 1.8, blast_radius: 'low' },
  { step: 'Decide if this invoice looks fraudulent', mode: 'deterministic', needs_judgement: true, output_shape: 'open', reversible: true, runs_per_day: 4000, cent_cost: 0.0, blast_radius: 'medium' },
  { step: 'Write the refusal email to the supplier', mode: 'agentic', needs_judgement: true, output_shape: 'open', reversible: false, runs_per_day: 60, cent_cost: 2.4, blast_radius: 'high' },
  { step: 'Convert currency using todays ECB rate', mode: 'agentic', needs_judgement: false, output_shape: 'fixed', reversible: true, runs_per_day: 4000, cent_cost: 1.1, blast_radius: 'low' },
  { step: 'Post the payment to the ledger', mode: 'agentic', needs_judgement: false, output_shape: 'fixed', reversible: false, runs_per_day: 900, cent_cost: 1.6, blast_radius: 'high' },
  { step: 'Summarise the month for the finance lead', mode: 'agentic', needs_judgement: true, output_shape: 'open', reversible: true, runs_per_day: 1, cent_cost: 9.0, blast_radius: 'low' }
];
return [{ json: { workflow_under_review: 'Invoice Triage', steps: steps } }];

const d = $input.first().json;
const verdicts = d.steps.map(function (s) {
  let belongs = 'DETERMINISTIC';
  let because = 'Fixed output shape and no judgement needed. A model here buys nothing and adds variance.';
  if (!s.reversible && s.blast_radius === 'high') {
    belongs = 'HUMAN';
    because = 'Irreversible and high blast radius. Judgement is cheap, an unrecoverable mistake is not.';
  } else if (s.needs_judgement && s.output_shape === 'open') {
    belongs = 'AGENTIC';
    because = 'Open-ended judgement over unstructured input. This is the part only a model can do.';
  }
  return {
    step: s.step,
    currently: s.mode.toUpperCase(),
    belongs: belongs,
    misplaced: belongs !== s.mode.toUpperCase(),
    because: because,
    daily_cents_now: Number((s.runs_per_day * s.cent_cost).toFixed(1)),
    daily_cents_after: belongs === 'AGENTIC' ? Number((s.runs_per_day * s.cent_cost).toFixed(1)) : 0
  };
});
return [{ json: { workflow_under_review: d.workflow_under_review, verdicts: verdicts } }];

const d = $input.first().json;
const misplaced = d.verdicts.filter(function (v) { return v.misplaced; });
const now = d.verdicts.reduce(function (a, v) { return a + v.daily_cents_now; }, 0);
const after = d.verdicts.reduce(function (a, v) { return a + v.daily_cents_after; }, 0);
const saved = Number(((now - after) / 100).toFixed(2));
const overAgentic = misplaced.filter(function (v) { return v.currently === 'AGENTIC' && v.belongs !== 'AGENTIC'; });
const underAgentic = misplaced.filter(function (v) { return v.belongs === 'AGENTIC' && v.currently !== 'AGENTIC'; });
const needsHuman = d.verdicts.filter(function (v) { return v.belongs === 'HUMAN' && v.currently !== 'HUMAN'; });
const plan = misplaced.map(function (v) { return 'Move \"' + v.step + '\" from ' + v.currently + ' to ' + v.belongs + '. ' + v.because; });
const say = misplaced.length + ' of ' + d.verdicts.length + ' steps are in the wrong place. ' +
  overAgentic.length + ' use a model where plain code would be exact, cheaper and repeatable. ' +
  underAgentic.length + ' use hard-coded rules where the input is genuinely open-ended. ' +
  needsHuman.length + ' are irreversible and should stop for a person. ' +
  'Fixing the over-agentic ones alone saves about EUR ' + saved + ' per day and removes that much non-determinism from the run.';
return [{ json: { plain_english: say, misplaced_count: misplaced.length, euro_saved_per_day: saved, over_agentic: overAgentic.length, under_agentic: underAgentic.length, needs_human: needsHuman.length, refactor_plan: plan, has_misplacements: misplaced.length > 0 } }];
